{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows sustained positive sentiment (e.g., >0.33) as it often signals overvaluation.",
    "Reduce forecast peaks after sharp spikes — model tends to overshoot post-spikes, especially when sentiment is neutral or positive.",
    "Apply mean reversion bias: if forecast is significantly above recent 5-day average, reduce by 5-10% to align with historical volatility.",
    "Increase downward bias when sentiment is negative (e.g., -0.25 or below) — model underreacts to bearish signals.",
    "For horizon >15 days, apply lag correction: forecast should be 3-5% lower than 30-day true outcome to account for delayed market reaction.",
    "When sentiment history includes multiple 0.50+ values, reduce forecast volatility — model overfits to recent sentiment trends."
  ]
}
